// ensureSSHKnownHosts seeds key ssh_known_hosts of ConfigMap patrol-ssh-known-hosts-cm with
// DefaultSSHKnownHosts, once: only when the ConfigMap exists, carries the part-of label (the
// settings layer ignores it otherwise) and has no such key. A present key, even empty, is
// never changed (it is managed through the API, or set by the operator). A missing ConfigMap
// is left missing: the install did not ship it (another tool owns it), and the certificate
// API creates it on the first change.
func (b *bootstrapper) ensureSSHKnownHosts(ctx context.Context) error {
	name := settings.DefaultSSHKnownHostsConfigMapName
	cms := b.cfg.Kube.CoreV1().ConfigMaps(b.cfg.Namespace)
	cm, err := cms.Get(ctx, name, metav1.GetOptions{})
	switch {
	case apierrors.IsNotFound(err):
		b.log.Info("known hosts ConfigMap not found; default known hosts not seeded", "configmap", name)
		return nil
	case err != nil:
		return fmt.Errorf("get ConfigMap %s/%s: %w", b.cfg.Namespace, name, err)
	}
	if cm.Labels[v1alpha1.LabelKeyPartOf] != v1alpha1.LabelValuePartOf {
		b.log.Warn("known hosts ConfigMap is not labelled "+v1alpha1.LabelKeyPartOf+"="+v1alpha1.LabelValuePartOf+
			" (ignored by Patrol); default known hosts not seeded", "configmap", name)
		return nil
	}
	if _, ok := cm.Data[settings.SSHKnownHostsKey]; ok {
		b.log.Info("known hosts present; unchanged", "configmap", name, "key", settings.SSHKnownHostsKey)
		return nil
	}
	updated := cm.DeepCopy()
	if updated.Data == nil {
		updated.Data = map[string]string{}
	}
	updated.Data[settings.SSHKnownHostsKey] = DefaultSSHKnownHosts
	// Guarded by the resourceVersion read above: a concurrent run (or an API write) makes it
	// fail with a conflict, and the retry re-reads the ConfigMap and finds the key.
	if _, err := cms.Update(ctx, updated, metav1.UpdateOptions{FieldManager: BootstrapFieldManager}); err != nil {
		return fmt.Errorf("update ConfigMap %s/%s: %w", b.cfg.Namespace, name, err)
	}
	b.log.Info("seeded the default known hosts", "configmap", name, "key", settings.SSHKnownHostsKey,
		"entries", strings.Count(DefaultSSHKnownHosts, "\n"))
	return nil
}
